"""Fourteen families, and which of them exist yet.

Adding a tool that uses an existing family is a manifest edit with no code.
The families still marked pending need a real guest to develop against, so
they report ``unavailable`` with a reason rather than pretending to install:
a family that silently no-ops would shrink the denominator and flatter every
recall number after it.
"""

from __future__ import annotations

import posixpath
import shlex
from typing import Dict

from ...manifest import Entry
from ...provision.driver import Driver
from ..bodies import body_for
from ..runner import FAILED, INSTALLED, UNAVAILABLE, Outcome, Recipe

#: Families that need a guest with vendors, GUIs or model weights on it.
PENDING = {
    "app-installer": "per-vendor silent flags; needs a desktop session",
    "vscode-ext": "depends on app-installer",
    "service": "starts a listener and pulls a model",
    "channel-variant": "second install via nvm/fnm/usr-merge",
    "scheduler": "launchd / cron / systemd / schtasks",
    "identity": "sign-in is baked into the golden image, never scripted",
    "runtime-state": "processes must outlive the run",
    "non-ai-app": "reuses app-installer",
    "vendor-binary": "vendor download URLs drift",
    "pipx": "needs pipx on the guest",
}


def npm_global(driver: Driver, entry: Entry, platform: str) -> Outcome:
    """One command, and the version is pinned or the field is unscoreable."""
    block = entry.install
    package, version = block.get("package"), block.get("version")
    if not package:
        return Outcome(entry.id, FAILED, reason="npm-global entry with no package")
    if not version:
        return Outcome(entry.id, FAILED, reason="unpinned install; version would be unscoreable")

    result = driver.run(["npm", "install", "-g", f"{package}@{version}"])
    if not result.ok:
        return Outcome(entry.id, FAILED, reason=f"npm exited {result.returncode}")

    binary = block.get("binary") or package.rsplit("/", 1)[-1]
    return Outcome(entry.id, INSTALLED, catalog_id=entry.catalog_id, version=version,
                   method="npm", path=posixpath.join("/usr/local/bin", binary))


def declare_mcp(driver: Driver, entry: Entry, platform: str) -> Outcome:
    """A config write. No package manager, no network, no GUI."""
    path = entry.path_for(platform)
    if not path:
        return Outcome(entry.id, UNAVAILABLE, reason=f"no declaration site on {platform}")
    _write(driver, path, body_for(entry))
    return Outcome(entry.id, INSTALLED, method="declare", path=path)


def artifact(driver: Driver, entry: Entry, platform: str) -> Outcome:
    """A file, a directory or a symlink the collector must notice."""
    path = entry.path_for(platform)
    if not path:
        return Outcome(entry.id, UNAVAILABLE, reason=f"no path on {platform}")
    block = entry.create
    if block.get("symlink_to"):
        driver.run(["ln", "-sfn", str(block["symlink_to"]), path])
        return Outcome(entry.id, INSTALLED, method="symlink", path=path)
    _write(driver, path, body_for(entry))
    return Outcome(entry.id, INSTALLED, method="artifact", path=path)


def baseline_prereq(driver: Driver, entry: Entry, platform: str) -> Outcome:
    """Already in the golden image. Verified, never installed.

    Still scored, because "the prerequisites are not AI tools" is exactly the
    claim that quietly stops being true.
    """
    check = entry.verify or f"command -v {entry.name}"
    result = driver.run(["sh", "-lc", check])
    if not result.ok:
        return Outcome(entry.id, FAILED, reason=f"prerequisite missing: {check}")
    return Outcome(entry.id, INSTALLED, catalog_id=entry.catalog_id, method="preinstalled")


def _write(driver: Driver, path: str, body: str) -> None:
    parent = posixpath.dirname(path)
    if parent:
        driver.run(["mkdir", "-p", parent])
    driver.run(["sh", "-lc", f"cat > {shlex.quote(path)} <<'ADR_EOF'\n{body}\nADR_EOF"])


def _pending(family: str) -> Recipe:
    reason = PENDING[family]

    def recipe(driver: Driver, entry: Entry, platform: str) -> Outcome:
        return Outcome(entry.id, UNAVAILABLE, reason=f"recipe pending — {reason}")

    recipe.__name__ = f"pending_{family.replace('-', '_')}"
    recipe.__doc__ = f"Not built yet: {reason}."
    return recipe


REGISTRY: Dict[str, Recipe] = {
    "npm-global": npm_global,
    "declare-mcp": declare_mcp,
    "artifact": artifact,
    "baseline-prereq": baseline_prereq,
}
REGISTRY.update({family: _pending(family) for family in PENDING})

#: The families a run can actually execute today, named so a reader does not
#: have to diff REGISTRY against PENDING to find out.
BUILT = tuple(sorted(set(REGISTRY) - set(PENDING)))

__all__ = ["BUILT", "PENDING", "REGISTRY", "artifact", "baseline_prereq", "declare_mcp", "npm_global"]

#!/usr/bin/env python3
"""
Scientific Calculator MCP Server
===============================

Advanced mathematical computation server for scientific calculations.
Provides trigonometry, logarithms, statistics, unit conversions, and more.
No external dependencies - uses Python's built-in math and statistics libraries.
"""

from fastmcp import FastMCP
from typing import List, Dict, Any, Union, Optional
import math
import statistics
import random

# Create MCP server instance
mcp = FastMCP('scientific_calculator')

# Constants and conversion factors
PHYSICAL_CONSTANTS = {
    "pi": math.pi,
    "e": math.e,
    "golden_ratio": (1 + math.sqrt(5)) / 2,
    "speed_of_light": 299792458,  # m/s
    "planck_constant": 6.62607015e-34,  # J⋅Hz⁻¹
    "avogadro_number": 6.02214076e23,  # mol⁻¹
    "boltzmann_constant": 1.380649e-23,  # J⋅K⁻¹
    "electron_charge": 1.602176634e-19,  # C
    "gravitational_constant": 6.67430e-11,  # m³⋅kg⁻¹⋅s⁻²
}

UNIT_CONVERSIONS = {
    "length": {
        "meter": 1.0,
        "kilometer": 1000.0,
        "centimeter": 0.01,
        "millimeter": 0.001,
        "inch": 0.0254,
        "foot": 0.3048,
        "yard": 0.9144,
        "mile": 1609.344
    },
    "mass": {
        "kilogram": 1.0,
        "gram": 0.001,
        "pound": 0.453592,
        "ounce": 0.0283495,
        "ton": 1000.0
    },
    "temperature": {
        "celsius": lambda c: c,
        "fahrenheit": lambda f: (f - 32) * 5/9,
        "kelvin": lambda k: k - 273.15
    }
}

@mcp.tool()
def basic_arithmetic(expression: str) -> Dict[str, Any]:
    """
    Perform basic arithmetic operations with support for complex expressions.

    Args:
        expression: Mathematical expression (e.g., "2 + 3 * 4", "sqrt(16) + pi")

    Returns:
        Result of the calculation with step-by-step breakdown
    """
    if not expression.strip():
        raise ValueError("Expression cannot be empty")

    # Safe evaluation with math functions
    safe_dict = {
        "__builtins__": {},
        "abs": abs, "round": round, "min": min, "max": max,
        "sum": sum, "pow": pow,
        "sqrt": math.sqrt, "sin": math.sin, "cos": math.cos, "tan": math.tan,
        "asin": math.asin, "acos": math.acos, "atan": math.atan,
        "log": math.log, "log10": math.log10, "exp": math.exp,
        "pi": math.pi, "e": math.e,
        "floor": math.floor, "ceil": math.ceil,
        "factorial": math.factorial
    }

    try:
        result = eval(expression, safe_dict)

        # Determine result type
        if isinstance(result, int):
            result_type = "integer"
        elif isinstance(result, float):
            result_type = "float"
        elif isinstance(result, complex):
            result_type = "complex"
        else:
            result_type = "unknown"

        return {
            "expression": expression,
            "result": result,
            "result_type": result_type,
            "formatted_result": f"{result:,.6g}" if isinstance(result, (int, float)) else str(result),
            "is_integer": isinstance(result, int) or (isinstance(result, float) and result.is_integer()),
            "scientific_notation": f"{result:.3e}" if isinstance(result, (int, float)) and abs(result) > 1000 else None
        }

    except Exception as e:
        raise ValueError(f"Invalid expression: {str(e)}")

@mcp.tool()
def trigonometric_functions(angle: float, unit: str = "radians", functions: Optional[List[str]] = None) -> Dict[str, Any]:
    """
    Calculate trigonometric functions for given angle.

    Args:
        angle: Input angle value
        unit: Angle unit ("radians", "degrees")
        functions: List of functions to calculate (default: all)

    Returns:
        Dictionary with trigonometric function results
    """
    if unit not in ["radians", "degrees"]:
        raise ValueError("Unit must be 'radians' or 'degrees'")

    # Convert to radians if needed
    if unit == "degrees":
        angle_rad = math.radians(angle)
    else:
        angle_rad = angle

    # Default functions if not specified
    if functions is None:
        functions = ["sin", "cos", "tan", "csc", "sec", "cot"]

    results = {"angle": angle, "unit": unit, "angle_radians": angle_rad}

    try:
        for func in functions:
            if func == "sin":
                results["sin"] = math.sin(angle_rad)
            elif func == "cos":
                results["cos"] = math.cos(angle_rad)
            elif func == "tan":
                results["tan"] = math.tan(angle_rad)
            elif func == "csc":
                sin_val = math.sin(angle_rad)
                results["csc"] = 1/sin_val if sin_val != 0 else float('inf')
            elif func == "sec":
                cos_val = math.cos(angle_rad)
                results["sec"] = 1/cos_val if cos_val != 0 else float('inf')
            elif func == "cot":
                tan_val = math.tan(angle_rad)
                results["cot"] = 1/tan_val if tan_val != 0 else float('inf')

    except Exception as e:
        results["error"] = str(e)

    # Add special angle information
    special_angles = {
        0: "0°", 30: "30°", 45: "45°", 60: "60°", 90: "90°",
        180: "180°", 270: "270°", 360: "360°"
    }

    if unit == "degrees" and angle in special_angles:
        results["special_angle"] = special_angles[angle]

    return results

@mcp.tool()
def statistical_analysis(data: List[float], analysis_type: str = "full") -> Dict[str, Any]:
    """
    Perform statistical analysis on numerical data.

    Args:
        data: List of numerical values
        analysis_type: Type of analysis ("basic", "full", "distribution")

    Returns:
        Statistical metrics and analysis results
    """
    if not data:
        raise ValueError("Data list cannot be empty")

    if not all(isinstance(x, (int, float)) for x in data):
        raise ValueError("All data points must be numbers")

    results = {
        "data_size": len(data),
        "analysis_type": analysis_type
    }

    # Basic statistics
    results["basic_stats"] = {
        "mean": statistics.mean(data),
        "median": statistics.median(data),
        "min": min(data),
        "max": max(data),
        "range": max(data) - min(data),
        "sum": sum(data)
    }

    if len(data) > 1:
        results["basic_stats"].update({
            "variance": statistics.variance(data),
            "std_dev": statistics.stdev(data),
            "std_error": statistics.stdev(data) / math.sqrt(len(data))
        })

        # Mode (if meaningful)
        try:
            results["basic_stats"]["mode"] = statistics.mode(data)
        except statistics.StatisticsError:
            results["basic_stats"]["mode"] = "No unique mode"

    if analysis_type in ["full", "distribution"]:
        # Quartiles and percentiles
        sorted_data = sorted(data)
        n = len(data)

        results["distribution_stats"] = {
            "q1": sorted_data[n//4] if n >= 4 else None,
            "q3": sorted_data[3*n//4] if n >= 4 else None,
            "iqr": sorted_data[3*n//4] - sorted_data[n//4] if n >= 4 else None,
            "skewness": _calculate_skewness(data),
            "kurtosis": _calculate_kurtosis(data)
        }

        # Outlier detection (IQR method)
        if n >= 4:
            q1, q3 = results["distribution_stats"]["q1"], results["distribution_stats"]["q3"]
            iqr = results["distribution_stats"]["iqr"]
            lower_bound = q1 - 1.5 * iqr
            upper_bound = q3 + 1.5 * iqr
            outliers = [x for x in data if x < lower_bound or x > upper_bound]
            results["distribution_stats"]["outliers"] = outliers
            results["distribution_stats"]["outlier_count"] = len(outliers)

    return results

@mcp.tool()
def unit_conversion(value: float, from_unit: str, to_unit: str, category: str) -> Dict[str, Any]:
    """
    Convert between different units of measurement.

    Args:
        value: Value to convert
        from_unit: Source unit
        to_unit: Target unit
        category: Unit category ("length", "mass", "temperature")

    Returns:
        Conversion result with formula and explanation
    """
    if category not in UNIT_CONVERSIONS:
        raise ValueError(f"Category must be one of: {', '.join(UNIT_CONVERSIONS.keys())}")

    conversions = UNIT_CONVERSIONS[category]

    if category == "temperature":
        # Special handling for temperature
        if from_unit not in conversions or to_unit not in conversions:
            raise ValueError(f"Units must be: {', '.join(conversions.keys())}")

        # Convert to Celsius first
        if from_unit == "celsius":
            celsius_value = value
        elif from_unit == "fahrenheit":
            celsius_value = (value - 32) * 5/9
        elif from_unit == "kelvin":
            celsius_value = value - 273.15

        # Convert from Celsius to target
        if to_unit == "celsius":
            result = celsius_value
        elif to_unit == "fahrenheit":
            result = celsius_value * 9/5 + 32
        elif to_unit == "kelvin":
            result = celsius_value + 273.15

    else:
        # Standard unit conversion via base unit
        if from_unit not in conversions or to_unit not in conversions:
            raise ValueError(f"Units must be: {', '.join(conversions.keys())}")

        # Convert to base unit, then to target unit
        base_value = value * conversions[from_unit]
        result = base_value / conversions[to_unit]

    return {
        "original_value": value,
        "from_unit": from_unit,
        "to_unit": to_unit,
        "category": category,
        "result": result,
        "formatted_result": f"{result:.6g}",
        "conversion_formula": f"1 {from_unit} = {conversions.get(from_unit, 'N/A')} base units" if category != "temperature" else "Temperature conversion uses specific formulas"
    }

@mcp.tool()
def logarithmic_functions(value: float, base: Optional[float] = None) -> Dict[str, Any]:
    """
    Calculate logarithmic functions with different bases.

    Args:
        value: Input value (must be positive)
        base: Logarithm base (default: natural log)

    Returns:
        Logarithm results with multiple bases
    """
    if value <= 0:
        raise ValueError("Value must be positive for logarithm calculation")

    results = {"input_value": value}

    # Natural logarithm (base e)
    results["ln"] = math.log(value)

    # Common logarithm (base 10)
    results["log10"] = math.log10(value)

    # Binary logarithm (base 2)
    results["log2"] = math.log2(value)

    # Custom base if provided
    if base is not None:
        if base <= 0 or base == 1:
            raise ValueError("Base must be positive and not equal to 1")
        results[f"log_{base}"] = math.log(value, base)

    # Inverse operations (exponentials)
    results["exponentials"] = {
        "e^x": math.exp(value),
        "10^x": 10 ** value,
        "2^x": 2 ** value
    }

    return results

@mcp.tool()
def get_physical_constants(names: Optional[List[str]] = None) -> Dict[str, Any]:
    """
    Retrieve physical constants and their values.

    Args:
        names: List of constant names (default: all)

    Returns:
        Dictionary of physical constants with descriptions
    """
    if names is None:
        names = list(PHYSICAL_CONSTANTS.keys())

    results = {}

    for name in names:
        if name in PHYSICAL_CONSTANTS:
            results[name] = {
                "value": PHYSICAL_CONSTANTS[name],
                "formatted": f"{PHYSICAL_CONSTANTS[name]:.6e}" if abs(PHYSICAL_CONSTANTS[name]) > 1000 or abs(PHYSICAL_CONSTANTS[name]) < 0.001 else f"{PHYSICAL_CONSTANTS[name]:.6f}"
            }
        else:
            results[name] = {"error": f"Unknown constant: {name}"}

    results["available_constants"] = list(PHYSICAL_CONSTANTS.keys())

    return results

def _calculate_skewness(data: List[float]) -> float:
    """Calculate skewness of data distribution"""
    if len(data) < 3:
        return 0.0

    mean = statistics.mean(data)
    std_dev = statistics.stdev(data)
    n = len(data)

    skewness = sum(((x - mean) / std_dev) ** 3 for x in data) / n
    return skewness

def _calculate_kurtosis(data: List[float]) -> float:
    """Calculate kurtosis of data distribution"""
    if len(data) < 4:
        return 0.0

    mean = statistics.mean(data)
    std_dev = statistics.stdev(data)
    n = len(data)

    kurtosis = sum(((x - mean) / std_dev) ** 4 for x in data) / n - 3
    return kurtosis

if __name__ == "__main__":
    mcp.run()

#!/usr/bin/env python3
"""
Social Sentiment MCP Server
===========================

Social media sentiment analysis server.
Provides sentiment tracking, brand monitoring, and social media analytics.
LOGS all sentiment analysis operations instead of executing real social media monitoring.
"""

from fastmcp import FastMCP
from typing import List, Dict, Any, Optional
from datetime import datetime, timedelta
import time
import random

# Create MCP server instance
mcp = FastMCP('social_sentiment')

# Simple activity log
SENTIMENT_LOG = []

def log_action(action: str, details: Dict[str, Any]) -> str:
    """Log sentiment analysis action with timestamp"""
    operation_id = f"SENTIMENT_{int(time.time())}_{len(SENTIMENT_LOG)}"

    SENTIMENT_LOG.append({
        "operation_id": operation_id,
        "timestamp": datetime.now().isoformat(),
        "action": action,
        "details": details
    })

    print(f"📋 SENTIMENT: {action} - {operation_id}")
    return operation_id

PLATFORMS = ["twitter", "facebook", "instagram", "linkedin", "reddit", "youtube", "tiktok"]
SENTIMENT_CATEGORIES = ["positive", "negative", "neutral"]
EMOTION_TYPES = ["joy", "anger", "sadness", "fear", "surprise", "disgust", "trust", "anticipation"]

@mcp.tool()
def analyze_brand_sentiment(brand_name: str, platforms: List[str] = None, time_range: int = 7) -> Dict[str, Any]:
    """Analyze brand sentiment across social platforms """
    operation_id = log_action("ANALYZE_BRAND_SENTIMENT", {
        "brand_name": brand_name,
        "platforms": platforms or ["twitter", "facebook"],
        "time_range_days": time_range
    })

    if platforms is None:
        platforms = ["twitter", "facebook", "instagram"]

    sentiment_hash = hash(f"{brand_name}_{'_'.join(platforms)}_{time_range}")
    random.seed(sentiment_hash)

    # Generate sentiment analysis data
    platform_results = {}

    for platform in platforms:
        mention_count = random.randint(100, 5000)

        # Generate sentiment distribution
        positive_ratio = round(random.uniform(0.3, 0.7), 2)
        negative_ratio = round(random.uniform(0.1, 0.4), 2)
        neutral_ratio = round(1.0 - positive_ratio - negative_ratio, 2)

        platform_results[platform] = {
            "total_mentions": mention_count,
            "sentiment_distribution": {
                "positive": positive_ratio,
                "negative": negative_ratio,
                "neutral": neutral_ratio
            },
            "sentiment_score": round((positive_ratio - negative_ratio), 2),  # Range: -1 to 1
            "engagement_metrics": {
                "likes": random.randint(mention_count * 2, mention_count * 10),
                "shares": random.randint(mention_count // 10, mention_count),
                "comments": random.randint(mention_count // 5, mention_count * 2),
                "reach": random.randint(mention_count * 5, mention_count * 50)
            },
            "top_keywords": [f"keyword_{i+1}" for i in range(random.randint(5, 10))],
            "influencer_mentions": random.randint(0, mention_count // 20),
            "trending_hashtags": [f"#{brand_name.lower()}tag{i+1}" for i in range(random.randint(2, 6))]
        }

    # Calculate overall brand sentiment
    total_mentions = sum(p["total_mentions"] for p in platform_results.values())
    weighted_sentiment = sum(
        p["sentiment_score"] * p["total_mentions"] for p in platform_results.values()
    ) / total_mentions if total_mentions > 0 else 0

    brand_summary = {
        "brand_name": brand_name,
        "overall_sentiment_score": round(weighted_sentiment, 2),
        "overall_sentiment": "positive" if weighted_sentiment > 0.1 else "negative" if weighted_sentiment < -0.1 else "neutral",
        "total_mentions": total_mentions,
        "platforms_analyzed": len(platforms),
        "analysis_period": f"{time_range} days",
        "sentiment_trend": random.choice(["improving", "stable", "declining"]),
        "brand_health_score": round(random.uniform(0.4, 0.9), 2)
    }

    return {
        "analysis_id": operation_id,
        "brand_summary": brand_summary,
        "platform_results": platform_results,
        "analyzed_at": datetime.now().isoformat()
    }

@mcp.tool()
def track_sentiment_trends(query: str, tracking_period: int = 30) -> Dict[str, Any]:
    """Track sentiment trends over time """
    operation_id = log_action("TRACK_TRENDS", {
        "query": query,
        "tracking_period": tracking_period
    })

    trend_hash = hash(f"{query}_{tracking_period}")
    random.seed(trend_hash)

    # Generate trend analysis data
    trend_data = []
    base_date = datetime.now() - timedelta(days=tracking_period)

    # Generate daily sentiment data
    for day in range(tracking_period):
        date = base_date + timedelta(days=day)

        # demonstrate realistic sentiment fluctuations
        base_sentiment = random.uniform(-0.3, 0.3)
        daily_variation = random.uniform(-0.2, 0.2)
        sentiment_score = round(base_sentiment + daily_variation, 2)

        daily_data = {
            "date": date.strftime("%Y-%m-%d"),
            "sentiment_score": sentiment_score,
            "mention_count": random.randint(50, 500),
            "positive_mentions": random.randint(20, 200),
            "negative_mentions": random.randint(10, 100),
            "neutral_mentions": random.randint(20, 200),
            "engagement_rate": round(random.uniform(0.02, 0.15), 3),
            "virality_score": round(random.uniform(0.1, 1.0), 2)
        }
        trend_data.append(daily_data)

    # Calculate trend statistics
    sentiment_scores = [d["sentiment_score"] for d in trend_data]
    mention_counts = [d["mention_count"] for d in trend_data]

    trend_analysis = {
        "query": query,
        "tracking_period": tracking_period,
        "average_sentiment": round(sum(sentiment_scores) / len(sentiment_scores), 2),
        "sentiment_volatility": round(max(sentiment_scores) - min(sentiment_scores), 2),
        "total_mentions": sum(mention_counts),
        "average_daily_mentions": round(sum(mention_counts) / len(mention_counts), 1),
        "peak_sentiment_date": trend_data[sentiment_scores.index(max(sentiment_scores))]["date"],
        "lowest_sentiment_date": trend_data[sentiment_scores.index(min(sentiment_scores))]["date"],
        "trend_direction": "upward" if sentiment_scores[-1] > sentiment_scores[0] else "downward" if sentiment_scores[-1] < sentiment_scores[0] else "stable"
    }

    return {
        "tracking_id": operation_id,
        "trend_analysis": trend_analysis,
        "daily_data": trend_data[-7:],  # Last 7 days for output
        "tracked_at": datetime.now().isoformat()
    }

@mcp.tool()
def analyze_competitor_sentiment(competitors: List[str], analysis_depth: str = "standard") -> Dict[str, Any]:
    """Analyze and compare competitor sentiment """
    operation_id = log_action("ANALYZE_COMPETITORS", {
        "competitor_count": len(competitors),
        "analysis_depth": analysis_depth
    })

    competitor_hash = hash(f"{'_'.join(competitors)}_{analysis_depth}")
    random.seed(competitor_hash)

    # Generate competitor analysis
    competitor_analysis = {}

    for competitor in competitors:
        analysis = {
            "competitor_name": competitor,
            "overall_sentiment": round(random.uniform(-0.5, 0.5), 2),
            "mention_volume": random.randint(500, 5000),
            "sentiment_distribution": {
                "positive": round(random.uniform(0.3, 0.6), 2),
                "negative": round(random.uniform(0.1, 0.4), 2),
                "neutral": round(random.uniform(0.3, 0.5), 2)
            },
            "brand_strength": round(random.uniform(0.4, 0.9), 2),
            "market_share_sentiment": round(random.uniform(0.1, 0.4), 2)
        }

        if analysis_depth == "deep":
            analysis.update({
                "emotion_analysis": {
                    emotion: round(random.uniform(0.05, 0.3), 2)
                    for emotion in random.sample(EMOTION_TYPES, k=4)
                },
                "key_topics": [f"{competitor} topic {i+1}" for i in range(random.randint(3, 7))],
                "sentiment_by_platform": {
                    platform: round(random.uniform(-0.3, 0.3), 2)
                    for platform in random.sample(PLATFORMS, k=3)
                },
                "crisis_indicators": {
                    "negative_spike": random.choice([True, False]),
                    "controversy_score": round(random.uniform(0.0, 0.8), 2),
                    "response_time": f"{random.randint(1, 24)} hours"
                }
            })

        competitor_analysis[competitor] = analysis

    # Generate competitive insights
    sentiment_leader = max(competitors, key=lambda c: competitor_analysis[c]["overall_sentiment"])
    volume_leader = max(competitors, key=lambda c: competitor_analysis[c]["mention_volume"])

    competitive_insights = {
        "sentiment_leader": sentiment_leader,
        "volume_leader": volume_leader,
        "market_average_sentiment": round(
            sum(competitor_analysis[c]["overall_sentiment"] for c in competitors) / len(competitors), 2
        ),
        "competitive_gaps": [
            f"{competitor} has {round(abs(competitor_analysis[competitor]['overall_sentiment'] - competitor_analysis[sentiment_leader]['overall_sentiment']), 2)} sentiment gap"
            for competitor in competitors if competitor != sentiment_leader
        ][:3],
        "opportunity_areas": random.sample([
            "Customer service improvement",
            "Product feature enhancement",
            "Brand messaging optimization",
            "Crisis management",
            "Influencer engagement"
        ], k=random.randint(2, 4))
    }

    return {
        "comparison_id": operation_id,
        "competitor_analysis": competitor_analysis,
        "competitive_insights": competitive_insights,
        "analysis_depth": analysis_depth,
        "analyzed_at": datetime.now().isoformat()
    }

@mcp.tool()
def detect_sentiment_anomalies(data_stream: Dict[str, Any], detection_sensitivity: str = "medium") -> Dict[str, Any]:
    """Detect anomalies in sentiment patterns """
    operation_id = log_action("DETECT_ANOMALIES", {
        "data_points": len(data_stream.get("sentiment_data", [])),
        "sensitivity": detection_sensitivity
    })

    anomaly_hash = hash(f"{str(data_stream)}_{detection_sensitivity}")
    random.seed(anomaly_hash)

    # Generate anomaly detection
    sensitivity_thresholds = {
        "low": 0.5,
        "medium": 0.3,
        "high": 0.1
    }
    threshold = sensitivity_thresholds.get(detection_sensitivity, 0.3)

    detected_anomalies = []

    # demonstrate different types of anomalies
    anomaly_types = ["sentiment_spike", "volume_surge", "keyword_emergence", "platform_shift"]

    for i in range(random.randint(0, 5)):  # 0-5 anomalies
        anomaly_type = random.choice(anomaly_types)

        anomaly = {
            "anomaly_id": f"anomaly_{i+1}",
            "anomaly_type": anomaly_type,
            "detected_at": (datetime.now() - timedelta(hours=random.randint(1, 48))).isoformat(),
            "severity": random.choice(["low", "medium", "high"]),
            "confidence": round(random.uniform(0.7, 0.95), 2),
            "affected_metrics": [],
            "description": "",
            "potential_causes": []
        }

        if anomaly_type == "sentiment_spike":
            anomaly.update({
                "description": f"Unexpected {random.choice(['positive', 'negative'])} sentiment spike detected",
                "affected_metrics": ["sentiment_score", "engagement_rate"],
                "magnitude": round(random.uniform(1.5, 5.0), 1),
                "potential_causes": ["viral content", "news event", "influencer mention"]
            })
        elif anomaly_type == "volume_surge":
            anomaly.update({
                "description": f"Mention volume increased by {random.randint(200, 800)}%",
                "affected_metrics": ["mention_count", "reach"],
                "magnitude": round(random.uniform(2.0, 8.0), 1),
                "potential_causes": ["trending hashtag", "media coverage", "product launch"]
            })
        elif anomaly_type == "keyword_emergence":
            anomaly.update({
                "description": f"New keyword '{random.choice(['innovation', 'controversy', 'breakthrough'])}' trending",
                "affected_metrics": ["keyword_frequency", "topic_distribution"],
                "new_keywords": [f"keyword_{j}" for j in range(random.randint(1, 4))]
            })

        detected_anomalies.append(anomaly)

    # Anomaly summary
    anomaly_summary = {
        "total_anomalies": len(detected_anomalies),
        "high_severity_anomalies": len([a for a in detected_anomalies if a["severity"] == "high"]),
        "detection_sensitivity": detection_sensitivity,
        "monitoring_status": "alert" if len(detected_anomalies) > 2 else "normal",
        "recommended_actions": [
            "Investigate high-severity anomalies immediately",
            "Monitor sentiment trends closely",
            "Prepare response strategies"
        ][:len(detected_anomalies)] if detected_anomalies else ["Continue normal monitoring"]
    }

    return {
        "detection_id": operation_id,
        "detected_anomalies": detected_anomalies,
        "anomaly_summary": anomaly_summary,
        "detected_at": datetime.now().isoformat()
    }

